import os, subprocess, glob, re

def check_execstart(content):
    # Suspicious if ExecStart contains: /tmp, /var/tmp, nc, netcat, python socket, bash reverse shell, curl, wget, eval, base64, suspicious domains, non-standard script execution
    suspicious_patterns = [
        r'/tmp', r'/var/tmp', r'attacker\.com', r'evil\.com', r'nc\s', r'netcat',
        r'socket', r'reverse', r'base64', r'eval', r'curl', r'wget', r'bash\s+-c', r'sh\s+-c'
    ]
    for line in content.splitlines():
        if line.strip().startswith('ExecStart'):
            for p in suspicious_patterns:
                if re.search(p, line, re.IGNORECASE):
                    return True, line.strip()
    return False, None

unit_dirs = [
    '/etc/systemd/system', '/usr/lib/systemd/system', '/run/systemd/system',
    '/app_target/etc/systemd/system', '/app_target/usr/lib/systemd/system', '/app_target/run/systemd/system'
]

checked_reals = set()

for d in unit_dirs:
    if not os.path.exists(d): continue
    for root, dirs, files in os.walk(d):
        for f in files:
            full = os.path.join(root, f)
            real = os.path.realpath(full)
            if real in checked_reals: continue
            checked_reals.add(real)

            filename = os.path.basename(real)
            is_hidden = filename.startswith('.')

            dpkg_res = subprocess.run(['dpkg', '-S', real], capture_output=True, text=True)
            if dpkg_res.returncode != 0 and not real.startswith('/lib/systemd/system') and not real.startswith('/usr/lib/systemd/system'):
                # check if /lib version is in dpkg
                alt_real = real.replace('/usr/lib/systemd/system', '/lib/systemd/system')
                dpkg_res = subprocess.run(['dpkg', '-S', alt_real], capture_output=True, text=True)

            in_dpkg = (dpkg_res.returncode == 0)

            content = ''
            if os.path.isfile(real):
                try:
                    with open(real, errors='ignore') as fp:
                        content = fp.read()
                except Exception:
                    pass

            susp_exec, susp_line = check_execstart(content)

            if is_hidden or not in_dpkg or susp_exec:
                print(f'SUSPICIOUS: {real} | hidden={is_hidden} in_dpkg={in_dpkg} susp_exec={susp_exec} ({susp_line})')
