    key = (art_type, real_path, line_no)
    if key in seen:
        return
    seen.add(key)

    file_hash = sha256_file(real_path)

    # preview max 100 chars
    if preview is not None:
        preview = preview.strip()[:100]

    artifacts.append({
        'type': art_type,
        'path': real_path,
        'sha256': file_hash,
        'details': {
            'line_number': line_no,
            'content_preview': preview,
            'user': user
        }
    })

# Define bases
bases = ['/app_target', ''] if os.path.exists('/app_target') else ['']

# 1. CRON JOBS
for b in bases:
    cron_files = []
    cron_files.extend(glob.glob(b + '/etc/cron.d/*'))
    if os.path.isfile(b + '/etc/crontab'): cron_files.append(b + '/etc/crontab')
    cron_files.extend(glob.glob(b + '/var/spool/cron/crontabs/*'))
    cron_files.extend(glob.glob(b + '/var/spool/cron/*'))
    cron_files.extend(glob.glob(b + '/etc/cron.daily/*'))
    cron_files.extend(glob.glob(b + '/etc/cron.hourly/*'))
    cron_files.extend(glob.glob(b + '/etc/cron.weekly/*'))
    cron_files.extend(glob.glob(b + '/etc/cron.monthly/*'))

    for cf in cron_files:
        if not os.path.isfile(cf): continue
        real_cf = os.path.realpath(cf)
        if os.path.basename(real_cf) == '.placeholder': continue

        try:
            with open(real_cf, 'r', errors='ignore') as fp:
                for line_idx, line in enumerate(fp, 1):
                    raw_line = line.strip()
                    if not raw_line or raw_line.startswith('#') or raw_line.startswith('SHELL=') or raw_line.startswith('PATH='):
                        continue

                    # Check suspicion
                    is_susp = False
                    # check /tmp, /var/tmp, /dev/shm
                    if re.search(r'/(tmp|var/tmp|dev/shm)', raw_line):
                        is_susp = True
                    # check suspicious tools/domains/cmds
                    elif re.search(r'(curl|wget|nc\s|netcat|base64|eval|python|perl|ruby|php|bash\s+-i|sh\s+-i|attacker|evil)', raw_line, re.I):
                        is_susp = True
                    # check non-standard paths
                    elif re.search(r'/(app_target|usr/local/bin|usr/local/sbin|home|root)', raw_line):
                        is_susp = True
                    # check timing * * * * *
                    elif raw_line.startswith('* * * * *') or raw_line.startswith('*/1 * * * *'):
                        is_susp = True

                    if is_susp:
                        # user detection for spool cron
                        user_val = None
                        if '/spool/cron/' in real_cf:
                            user_val = os.path.basename(real_cf)
                        add_artifact('cron_job', real_cf, line_idx, raw_line, user_val)
        except Exception as e:
            pass

# 2. SYSTEMD UNITS
for b in bases:
    systemd_dirs = [b + s for s in ['/etc/systemd/system', '/usr/lib/systemd/system', '/run/systemd/system', '/lib/systemd/system']]
    for sd in systemd_dirs:
        if not os.path.exists(sd): continue
        for root, dirs, files in os.walk(sd):
            for f in files:
                full_p = os.path.join(root, f)
                real_p = os.path.realpath(full_p)
                if not os.path.isfile(real_p): continue

                fname = os.path.basename(real_p)
                is_hidden = fname.startswith('.')

                # dpkg check
                alt_lib = real_p.replace('/usr/lib/', '/lib/') if '/usr/lib/' in real_p else real_p
                dpkg_1 = subprocess.run(['dpkg', '-S', real_p], capture_output=True, text=True)
                dpkg_2 = subprocess.run(['dpkg', '-S', alt_lib], capture_output=True, text=True)
                in_dpkg = (dpkg_1.returncode == 0 or dpkg_2.returncode == 0)

                # Check ExecStart and content
                exec_line = None
                has_susp_exec = False
                file_content = ''
                try:
                    with open(real_p, 'r', errors='ignore') as fp:
                        file_content = fp.read()
                    for l in file_content.splitlines():
                        if l.strip().startswith('ExecStart'):
                            exec_line = l.strip()
                            if re.search(r'/(tmp|var/tmp|dev/shm|app_target|usr/local)', l) or \
                               re.search(r'(curl|wget|nc\s|netcat|python|perl|ruby|socket|reverse|attacker|evil|bash\s+-c|sh\s+-c)', l, re.I):
                                has_susp_exec = True
                except Exception:
                    pass

                if is_hidden or (not in_dpkg and (has_susp_exec or '/etc/systemd/system' in real_p or '/app_target' in real_p)):
                    preview = exec_line if exec_line else file_content.splitlines()[0] if file_content else ''
                    add_artifact('systemd_unit', real_p, None, preview, None)

# 3. RC.LOCAL
for b in bases:
    rc_files = [b + '/etc/rc.local', b + '/etc/rc.d/rc.local']
    for rf in rc_files:
        if not os.path.isfile(rf): continue
        real_rf = os.path.realpath(rf)
        try:
            with open(real_rf, 'r', errors='ignore') as fp:
                for line_idx, line in enumerate(fp, 1):
                    raw_line = line.strip()
                    if not raw_line or raw_line.startswith('#') or raw_line.startswith('#!/') or raw_line == 'exit 0':
                        continue
