        if m:
            user_val = m.group(1)
        elif '/root/.ssh' in real_sf:
            user_val = 'root'

        try:
            with open(real_sf, 'r', errors='ignore') as fp:
                for line_idx, line in enumerate(fp, 1):
                    raw_line = line.strip()
                    if not raw_line or raw_line.startswith('#'):
                        continue

                    # check if suspicious
                    is_susp = False
                    if '/app_target/' in real_sf:
                        is_susp = True
                    elif re.search(r'(attacker|backdoor|malicious|evil|unknown|hack|shell)', raw_line, re.I):
                        is_susp = True
                    elif LEGIT_KEY_SUBSTR not in raw_line:
