                    if is_susp:
                        add_artifact('ssh_key', real_sf, line_idx, raw_line, user_val)
        except Exception:
            pass

# Sort artifacts by type, then by path, then by line_number
artifacts.sort(key=lambda x: (x['type'], x['path'], x['details']['line_number'] or 0))

